local TapestryLoom = {}
local PRODUCTS = {
    linen_hanging = { name = "Lnena obešalka", linenCost = 2, time = 2, cost = 25, warmth = 5, description = "Preprosta lnena obešalka za zid." },
    wool_tapestry = { name = "Volnena tapiserija", woolCost = 2, time = 4, cost = 90, warmth = 10, prestige = 2, description = "Volnena tapiserija z geometrijskimi vzorci." },
    dyed_tapestry = { name = "Barvna tapiserija", woolCost = 2, dyeCost = 1, time = 5, cost = 200, warmth = 12, prestige = 5, happiness = 1, description = "Barvno pletena tapiserija z rastlinskimi motivi." },
    silk_tapestry = { name = "Svila tapiserija", silkCost = 2, woolCost = 1, time = 7, cost = 480, warmth = 14, prestige = 12, happiness = 2, description = "Svilena tapiserija za plemiške dvorane." },
    gold_thread_tapestry = { name = "Zlato nitna tapiserija", silkCost = 2, goldCost = 1, dyeCost = 1, time = 10, cost = 1000, warmth = 15, prestige = 22, happiness = 4, description = "Tapiserija z zlatimi niti za kraljeve dvorane." },
    royal_hunt_tapestry = { name = "Kraljevski lovna tapiserija", silkCost = 3, goldCost = 2, silverCost = 1, jewelCost = 1, dyeCost = 2, time = 16, cost = 2800, warmth = 20, prestige = 60, happiness = 12, description = "Veliki kraljevski lovni prizor z dragocenimi nitmi in dragulji." },
}
local BUILDINGS = {
    workshop = { name = "Tapestirska delavnica", cost = { gold = 280, wood = 150 }, upkeep = 7, qualityBonus = 5 },
    loom_room = { name = "Stenska soba", cost = { gold = 850, wood = 250, stone = 200, wool = 10 }, upkeep = 20, qualityBonus = 18 },
    dyeing_chamber = { name = "Barvilnica", cost = { gold = 1900, wood = 300, stone = 400, silver = 30, dye = 8 }, upkeep = 45, qualityBonus = 30 },
    royal_tapestry_atelier = { name = "Kraljevski atelje tapiserij", cost = { gold = 7000, wood = 600, stone = 800, gold = 80, silk = 20 }, upkeep = 130, qualityBonus = 55, prestigeBonus = 33 },
}
TapestryLoom.linenStock = 12; TapestryLoom.woolStock = 14; TapestryLoom.silkStock = 8; TapestryLoom.dyeStock = 8; TapestryLoom.goldStock = 6; TapestryLoom.silverStock = 6; TapestryLoom.jewelStock = 4
TapestryLoom.productStock = {}; TapestryLoom.buildings = {}; TapestryLoom.maker = nil; TapestryLoom.activeMaking = {}; TapestryLoom.totalProducts = 0; TapestryLoom.dayTimer = 0
function TapestryLoom.init() TapestryLoom.linenStock=12; TapestryLoom.woolStock=14; TapestryLoom.silkStock=8; TapestryLoom.dyeStock=8; TapestryLoom.goldStock=6; TapestryLoom.silverStock=6; TapestryLoom.jewelStock=4; TapestryLoom.productStock={}; TapestryLoom.buildings={}; TapestryLoom.maker=nil; TapestryLoom.activeMaking={}; TapestryLoom.totalProducts=0; TapestryLoom.dayTimer=0; print("[TapestryLoom] Royal Tapestry Loom System initialized (6 products, 4 buildings)") end
function TapestryLoom.hireMaker(n,s) s=s or math.random(50,90); local c=480+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TapestryLoom.maker={name=n or ("Tapestirar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tapestirar najet: %s (spretnost: %d)",TapestryLoom.maker.name,s),"success") end; return true end
function TapestryLoom.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TapestryLoom.build(id) local ok,e=TapestryLoom.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TapestryLoom.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TapestryLoom.getQualityBonus() local b=0; for _,bd in ipairs(TapestryLoom.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TapestryLoom.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.linenCost and TapestryLoom.linenStock<(d.linenCost or 0) then return false,"Premalo lana" end; if d.woolCost and TapestryLoom.woolStock<(d.woolCost or 0) then return false,"Premalo volne" end; if d.silkCost and TapestryLoom.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.dyeCost and TapestryLoom.dyeStock<(d.dyeCost or 0) then return false,"Premalo barvila" end; if d.goldCost and TapestryLoom.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.silverCost and TapestryLoom.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.jewelCost and TapestryLoom.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #TapestryLoom.buildings==0 then return false,"Potrebna delavnica" end; if not TapestryLoom.maker then return false,"Potreben tapestirar" end; return true end
function TapestryLoom.make(pt,qty) qty=qty or 1; local ok,e=TapestryLoom.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.linenCost then TapestryLoom.linenStock=TapestryLoom.linenStock-d.linenCost*qty end; if d.woolCost then TapestryLoom.woolStock=TapestryLoom.woolStock-d.woolCost*qty end; if d.silkCost then TapestryLoom.silkStock=TapestryLoom.silkStock-d.silkCost*qty end; if d.dyeCost then TapestryLoom.dyeStock=TapestryLoom.dyeStock-d.dyeCost*qty end; if d.goldCost then TapestryLoom.goldStock=TapestryLoom.goldStock-d.goldCost*qty end; if d.silverCost then TapestryLoom.silverStock=TapestryLoom.silverStock-d.silverCost*qty end; if d.jewelCost then TapestryLoom.jewelStock=TapestryLoom.jewelStock-d.jewelCost*qty end; local t=d.time; if TapestryLoom.maker then t=math.max(1,t-math.floor(TapestryLoom.maker.skill/12)) end; table.insert(TapestryLoom.activeMaking,{id="tapestry_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,warmth=d.warmth or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TapestryLoom.completeMaking(m) local q=1.0+(TapestryLoom.getQualityBonus()/100); if TapestryLoom.maker then q=q+(TapestryLoom.maker.skill/180) end; q=math.min(2.0,q); TapestryLoom.productStock[m.productType]=(TapestryLoom.productStock[m.productType] or 0)+m.quantity; TapestryLoom.totalProducts=TapestryLoom.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TapestryLoom.maker then TapestryLoom.maker.itemsMade=TapestryLoom.maker.itemsMade+m.quantity; if math.random()<0.20 then TapestryLoom.maker.skill=math.min(100,TapestryLoom.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tapiserija izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"tapestry.completed",{productName=m.productName,prestige=m.prestige}) end end
function TapestryLoom.update(dt) if not _G.state then return end; TapestryLoom.dayTimer=TapestryLoom.dayTimer+dt; if TapestryLoom.dayTimer>=30 then TapestryLoom.dayTimer=0; for i=#TapestryLoom.activeMaking,1,-1 do local m=TapestryLoom.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TapestryLoom.completeMaking(m); table.remove(TapestryLoom.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TapestryLoom.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TapestryLoom.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TapestryLoom.getStats() return {linenStock=TapestryLoom.linenStock,woolStock=TapestryLoom.woolStock,silkStock=TapestryLoom.silkStock,dyeStock=TapestryLoom.dyeStock,goldStock=TapestryLoom.goldStock,silverStock=TapestryLoom.silverStock,jewelStock=TapestryLoom.jewelStock,productStock=TapestryLoom.productStock,numBuildings=#TapestryLoom.buildings,hasMaker=TapestryLoom.maker~=nil,makerName=TapestryLoom.maker and TapestryLoom.maker.name or "—",makerSkill=TapestryLoom.maker and TapestryLoom.maker.skill or 0,activeMaking=#TapestryLoom.activeMaking,totalProducts=TapestryLoom.totalProducts} end
return TapestryLoom
